using RealmGate.App.Models;
namespace RealmGate.App.Services;
public sealed class HostCleanupScheduler : IHostCleanupScheduler
{
    private readonly IReforgedHostController _host; private readonly IApplicationSettingsService _settings; private readonly IAppLogger _logger;
    private readonly SemaphoreSlim _gate=new(1,1); private Timer? _timer; private HostLaunchOptions _options=new(AppContext.BaseDirectory); private DateTimeOffset? _postponedUntil;
    public HostCleanupSchedule Schedule=>_settings.Current.HostCleanup; public DateTimeOffset? NextCleanupAt{get;private set;} public HostCleanupSchedulerState State{get;private set;}=HostCleanupSchedulerState.Disabled; public string StatusMessage{get;private set;}="Automatic reset disabled"; public event EventHandler? StateChanged;
    public HostCleanupScheduler(IReforgedHostController host,IApplicationSettingsService settings,IAppLogger logger){_host=host;_settings=settings;_logger=logger;Reschedule();}
    public void UpdateLaunchOptions(HostLaunchOptions options)=>_options=options;
    public async Task UpdateScheduleAsync(HostCleanupSchedule schedule,CancellationToken token){_settings.Current.HostCleanup=schedule;await _settings.SaveAsync();_postponedUntil=null;Reschedule();}
    public Task CancelPendingCleanupAsync(CancellationToken token){Schedule.Enabled=false;return UpdateScheduleAsync(Schedule,token);}
    public Task PostponeAsync(TimeSpan duration,CancellationToken token){if(duration<=TimeSpan.Zero)throw new ArgumentOutOfRangeException(nameof(duration));_postponedUntil=DateTimeOffset.Now.Add(duration);NextCleanupAt=_postponedUntil;Set(HostCleanupSchedulerState.Waiting,$"Reset postponed until {NextCleanupAt:ddd MMM d, h:mm tt}");Arm();return Task.CompletedTask;}
    public async Task RunCleanupNowAsync(CancellationToken token){await _gate.WaitAsync(token);try{Set(HostCleanupSchedulerState.Running,"Scheduled cleanup/reset running");_logger.Info(Schedule.DisconnectMessage);if(_host.State==HostControllerState.Running){if(Schedule.RestartHostAfterCleanup)await _host.RestartAsync(_options,token);else await _host.StopAsync(token);}else if(Schedule.RestartHostAfterCleanup)await _host.StartAsync(_options,token);_logger.Info("Scheduled Host cleanup/reset completed through graceful runtime restart.");_postponedUntil=null;Reschedule();}catch(Exception ex){Set(HostCleanupSchedulerState.Failed,ex.Message);_logger.Error("Scheduled Host cleanup/reset failed.",ex);throw;}finally{_gate.Release();}}
    private void Reschedule(){_timer?.Dispose();if(!Schedule.Enabled){NextCleanupAt=null;Set(HostCleanupSchedulerState.Disabled,"Automatic reset disabled");return;}NextCleanupAt=_postponedUntil??CalculateNext(DateTimeOffset.Now);Set(HostCleanupSchedulerState.Waiting,$"Next reset: {NextCleanupAt:ddd MMM d, h:mm tt}");Arm();}
    private void Arm(){_timer?.Dispose();if(NextCleanupAt is null)return;var due=NextCleanupAt.Value-DateTimeOffset.Now;if(due<TimeSpan.Zero)due=TimeSpan.Zero;_timer=new Timer(async _=>{try{await RunCleanupNowAsync(CancellationToken.None);}catch{}},null,due,Timeout.InfiniteTimeSpan);}
    private DateTimeOffset CalculateNext(DateTimeOffset now){if(!TimeOnly.TryParse(Schedule.CleanupTime,out var time))time=new TimeOnly(4,0);TimeZoneInfo zone;try{zone=TimeZoneInfo.FindSystemTimeZoneById(Schedule.TimeZoneId);}catch{zone=TimeZoneInfo.Local;}var local=TimeZoneInfo.ConvertTime(now,zone);for(var i=0;i<8;i++){var day=local.Date.AddDays(i);if(Schedule.Frequency==CleanupFrequency.SelectedDays&&!Schedule.Days.Contains(day.DayOfWeek))continue;var candidate=new DateTime(day.Year,day.Month,day.Day,time.Hour,time.Minute,0,DateTimeKind.Unspecified);var dto=new DateTimeOffset(candidate,zone.GetUtcOffset(candidate));if(dto>now)return dto;}return now.AddDays(1);}
    private void Set(HostCleanupSchedulerState state,string message){State=state;StatusMessage=message;StateChanged?.Invoke(this,EventArgs.Empty);}
    public ValueTask DisposeAsync(){_timer?.Dispose();_gate.Dispose();return ValueTask.CompletedTask;}
}
